PARAMS = {"revolve_deg": 360.0}


def _check_params():
    p = PARAMS
    if not (0 < p["revolve_deg"] <= 360):
        raise ValueError(f"revolve_deg 必須在 (0, 360],目前 {p['revolve_deg']}")


def gen_step():
    _check_params()
    return SurfaceBuilder(SURFACE_SPEC, PARAMS).build()


def check_geometry(shape):
    check_surface_model(shape, SURFACE_SPEC)
